#!/usr/bin/env python3
"""Outer-loop campaign runner for the ARM64 SDC fuzzing flow."""

from __future__ import annotations

import argparse
import json
from dataclasses import asdict, dataclass
from pathlib import Path
from typing import Any, Dict, List, Mapping, Optional

from run_sdc_differential import (
    DEFAULT_GEM5_CONFIG,
    DEFAULT_GEM5_OUTDIR,
    run_differential,
)
from sdc_materialize import materialize_testcase
from sdc_preflight import (
    DEFAULT_GEM5_BINARY,
    DEFAULT_MCPAT_BINARY,
    run_preflight,
)
from sdc_scheduler import FeedbackScheduler, RankedCandidate
from sdc_vault import SDCVault


REPO_ROOT = Path(__file__).resolve().parent
DEFAULT_OUTPUT_ROOT = REPO_ROOT / "artifacts" / "campaign"


@dataclass(frozen=True)
class CampaignRun:
    testcase_key: str
    source_path: Optional[str]
    action: str
    scheduler_status: str
    fitness: float
    result_status: Optional[str] = None
    result_json: Optional[str] = None
    artifact_dir: Optional[str] = None
    error: Optional[str] = None


def _load_metadata(metadata_json: Any) -> Dict[str, Any]:
    if isinstance(metadata_json, dict):
        return dict(metadata_json)
    if metadata_json in (None, ""):
        return {}
    return json.loads(str(metadata_json))


def resolve_source_path(
    candidate: RankedCandidate, source_root: Optional[Path]
) -> Optional[Path]:
    explicit = candidate.metadata.get("source_path")
    if explicit:
        return Path(str(explicit)).expanduser().resolve()
    if source_root is None:
        return None
    return (source_root / f"{candidate.testcase_key}.c").resolve()


def _update_campaign_metadata(
    vault: SDCVault,
    testcase_key: str,
    *,
    source_path: Path,
    artifact_dir: Path,
    result_json: Path,
) -> None:
    row = vault.get_testcase(testcase_key)
    if row is None:
        return
    metadata = _load_metadata(row["metadata_json"])
    metadata["source_path"] = str(source_path)
    metadata["campaign"] = {
        "artifact_dir": str(artifact_dir),
        "result_json": str(result_json),
    }
    vault.update_execution_result(testcase_key, metadata=metadata)

