@dataclass
class CommandResult:
    command: List[str]
    returncode: int
    stdout: str
    stderr: str
    timed_out: bool = False

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)


@dataclass
class DifferentialResult:
    status: str
    golden_digest: Optional[str]
    faulted_digest: Optional[str]
