ArmBareMetalProcess::ArmBareMetalProcess(
        const ProcessParams &params,
        loader::ObjectFile *objFile, loader::Arch _arch)
    : ArmProcess(params, objFile, _arch)
{
    // Use a simple memory layout: stack at 0x80000000 (2GB), 64KB
    // For bare-metal, we don't use the memState-based mmap
    Addr brk_point = roundUp(image.maxAddr(), PageBytes);
    Addr stack_base = 0x80000000L;
    Addr max_stack_size = 0x10000; // 64KB
    Addr next_thread_stack_base = stack_base - max_stack_size;
    Addr mmap_end = 0x40000000L;

    memState = std::make_shared<MemState>(
            this, brk_point, stack_base, max_stack_size,
            next_thread_stack_base, mmap_end);
}

void
ArmBareMetalProcess::initState()
{
    // Call parent's Process::initState() to load ELF segments
    // This calls pTable->initState() and image.write()
    Process::initState();

    // Manually map a stack region at 0x80000000 (inside physical mem range)
    // Allocate 64KB of stack space
    allocateMem(0x80000000L, 0x10000, false);

    // Map a small TLS/thread area at 0x81000000 if needed
    // allocateMem(0x81000000L, 0x1000, false);

    // Now manually set SP via SETranslatingPortProxy
    ThreadContext *tc = system->threads[contextIds[0]];

    // Stack grows downward from 0x80010000 (64KB - 16 bytes for alignment)
    Addr stack_top = 0x80010000L;
    SETranslatingPortProxy proxy(tc);
    uint64_t sp_val = stack_top;
    proxy.writeBlob(0x8000FFE8, (uint8_t*)&sp_val, sizeof(sp_val));

    // Set SP register to point at the stack top
    // Using the X31 register (SP is banked)
    tc->setReg(int_reg::Sp0, stack_top);

    // Set CPSR for EL0 (user mode)
    CPSR cpsr = tc->readMiscReg(MISCREG_CPSR);
    cpsr.mode = MODE_EL0T;
    tc->setMiscReg(MISCREG_CPSR, cpsr);

    // Enable floating point / NEON
    CPACR cpacr = tc->readMiscReg(MISCREG_CPACR_EL1);
    cpacr.cp10 = 0x3;
    cpacr.cp11 = 0x3;
    cpacr.zen = 0x3;
    tc->setMiscReg(MISCREG_CPACR_EL1, cpacr);
    FPEXC fpexc = tc->readMiscReg(MISCREG_FPEXC);
    fpexc.en = 1;
    tc->setMiscReg(MISCREG_FPEXC, fpexc);

    // Activate thread 0, suspend others
    tc->activate();
    for (size_t i = 1; i < contextIds.size(); ++i) {
        system->threads[contextIds[i]]->suspend();
    }
}

