           ArmISA::Arm_Fphp | ArmISA::Arm_Asimdhp | ArmISA::Arm_Fcma |
           ArmISA::Arm_Aes | ArmISA::Arm_Pmull | ArmISA::Arm_Sha1 |
           ArmISA::Arm_Sha2 | ArmISA::Arm_Crc32;
}

