{}

void
BareMetalWorkload::initState()
{
    SEWorkload::initState();

    // Activate first thread, suspend others
    // PC and registers are already set by ArmBareMetalProcess64::initState()
    for (auto *tc: system->threads) {
        if (tc->contextId() == 0) {
            tc->activate();
        } else {
            tc->suspend();
        }
    }
}

