BareMetalWorkload::initState()
{
    SEWorkload::initState();

    // Get entry point from the first process via ThreadContext
    ThreadContext *tc = system->threads[0];
    Process *proc = tc->getProcessPtr();
    Addr entry = proc->objFile->entryPoint();

