49	
50	ArmBareMetalProcess32::ArmBareMetalProcess32(
51	        const ProcessParams &params,
52	        loader::ObjectFile *objFile, loader::Arch _arch)
53	    : ArmProcess32(params, objFile, _arch)
54	{
55	    // For bare-metal: stack at 0x80000000 (2GB), 64KB — within physical mem
56	    Addr brk_point = roundUp(image.maxAddr(), PageBytes);
57	    Addr stack_base = 0x80000000L;
58	    Addr max_stack_size = 0x10000; // 64KB
59	    Addr next_thread_stack_base = stack_base - max_stack_size;
60	    Addr mmap_end = 0x40000000L;
61	
62	    memState = std::make_shared<MemState>(
63	            this, brk_point, stack_base, max_stack_size,
64	            next_thread_stack_base, mmap_end);
65	}
66	
67	void
68	ArmBareMetalProcess32::initState()
69	{
70	    // Call Process::initState() to load ELF segments and init page table
71	    Process::initState();
72	
73	    // Manually allocate and map stack at 0x80000000 (inside physical mem range)
74	    allocateMem(0x80000000L, 0x10000, false);
75	
76	    ThreadContext *tc = system->threads[contextIds[0]];
